import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{"title":"Getting Started","order":1},"headers":[],"relativePath":"learn/mod/index.md","filePath":"learn/mod/index.md","lastUpdated":1786943111000}'),s={name:"learn/mod/index.md"};function n(d,t,l,o,h,p){return a(),i("div",null,[...t[0]||(t[0]=[r(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Welcome to the ADOFAI Mod development tutorial. This series will guide you <strong>step by step</strong> through building a Mod for <em>A Dance of Fire and Ice</em> (ADOFAI).</p><p>The series has 26 chapters organized into five stages:</p><table tabindex="0"><thead><tr><th>Stage</th><th>Chapters</th><th>What you get</th></tr></thead><tbody><tr><td>☕ Prerequisites</td><td>0</td><td>C# basics crash course (for complete beginners)</td></tr><tr><td>🚀 Getting Started</td><td>1–5</td><td>Environment, how UMM works, your first Mod, debugging</td></tr><tr><td>🧩 Harmony</td><td>6–16</td><td>The full patch series (incl. Transpiler, Reverse Patch)</td></tr><tr><td>🛠️ Practice</td><td>17–19</td><td>Settings UI, locating target methods</td></tr><tr><td>🚢 Advanced &amp; Publishing</td><td>20–25</td><td>Multi-loader, Mod API, CI/CD, guidelines</td></tr></tbody></table><p>Before you begin, you should have the following background:</p><ol><li><strong>Never learned C#?</strong> Read <a href="./csharp-basics">C# Basics Crash Course</a> first — go through chapter 0</li><li>Some experience with <strong>Git and GitHub</strong></li></ol><h2 id="environment-setup" tabindex="-1">Environment Setup <a class="header-anchor" href="#environment-setup" aria-label="Permalink to &quot;Environment Setup&quot;">​</a></h2><h3 id="_1-prepare-the-game" tabindex="-1">1. Prepare the game <a class="header-anchor" href="#_1-prepare-the-game" aria-label="Permalink to &quot;1. Prepare the game&quot;">​</a></h3><ul><li>Purchase and install <em>A Dance of Fire and Ice</em> on Steam</li><li>Make sure the game launches correctly</li></ul><h3 id="_2-install-unitymodmanager" tabindex="-1">2. Install UnityModManager <a class="header-anchor" href="#_2-install-unitymodmanager" aria-label="Permalink to &quot;2. Install UnityModManager&quot;">​</a></h3><ol><li>Download <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">UnityModManager</a> (0.27.0 or newer)</li><li>Run UMM and select ADOFAI in the game list</li><li>Click <strong>Install</strong> to inject UMM into the game</li></ol><h3 id="_3-install-development-tools" tabindex="-1">3. Install development tools <a class="header-anchor" href="#_3-install-development-tools" aria-label="Permalink to &quot;3. Install development tools&quot;">​</a></h3><ul><li><strong>Visual Studio 2019+</strong> or <strong>JetBrains Rider</strong></li><li><strong>.NET Framework 4.8.1 Developer Pack</strong></li><li><strong>Harmony 2.3.3</strong></li></ul><h3 id="_4-get-the-official-template" tabindex="-1">4. Get the official template <a class="header-anchor" href="#_4-get-the-official-template" aria-label="Permalink to &quot;4. Get the official template&quot;">​</a></h3><p>The organization provides two Mod templates; this series uses the first one:</p><table tabindex="0"><thead><tr><th>Template</th><th>Description</th></tr></thead><tbody><tr><td><a href="https://github.com/adofaiex/ADOFAIModTemplate" target="_blank" rel="noreferrer">ADOFAIModTemplate</a></td><td>Base template, the star of this series</td></tr><tr><td><a href="https://github.com/adofaiex/ADOFAIMod.MultiLoader" target="_blank" rel="noreferrer">ADOFAIMod.MultiLoader</a></td><td>Advanced multi-loader template, see the <a href="./multiloader">advanced chapter</a></td></tr></tbody></table><p>Clone and install the base template:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/adofaiex/ADOFAIModTemplate.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ADOFAIModTemplate</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install as a local template (from the repo directory)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DOFAIModTemplate</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or install from the NuGet package</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tArray.ADOFAIModTemplate.1.0.0.nupkg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="_5-verify-the-environment" tabindex="-1">5. Verify the environment <a class="header-anchor" href="#_5-verify-the-environment" aria-label="Permalink to &quot;5. Verify the environment&quot;">​</a></h3><p>Create a test project from the template:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ADOFAIModTemplate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MyFirstMod</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>If the generated project contains <code>src/Main.cs</code>, <code>src/Settings.cs</code>, and <code>src/Patches.cs</code>, your environment is ready.</p><h2 id="debugging-your-mod" tabindex="-1">Debugging Your Mod <a class="header-anchor" href="#debugging-your-mod" aria-label="Permalink to &quot;Debugging Your Mod&quot;">​</a></h2><ul><li>UMM uses runtime injection; debugging requires launching the game itself</li><li>Enable / disable Mods in the UMM overlay (default <code>Ctrl+F10</code>)</li><li>Check the game log to confirm the Mod loaded successfully</li></ul><h2 id="development-principles" tabindex="-1">Development Principles <a class="header-anchor" href="#development-principles" aria-label="Permalink to &quot;Development Principles&quot;">​</a></h2><p>Thank you for contributing to the ADOFAI ecosystem. Please follow these principles when developing Mods:</p><ul><li>Test your features</li><li>Include good comments</li><li>Store persistent data in the Mod&#39;s local config directory so updates don&#39;t overwrite it</li><li>Handle errors gracefully — never let a single failure crash the whole Mod</li><li>If you&#39;re extending an existing Mod, prefer submitting a PR to the original project</li></ul><h2 id="chapters" tabindex="-1">Chapters <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters&quot;">​</a></h2><p>The full chapter list is below; reading in order is recommended:</p><table tabindex="0"><thead><tr><th>#</th><th>Chapter</th><th>Content</th></tr></thead><tbody><tr><td>0</td><td><a href="./csharp-basics">C# Basics Crash Course</a></td><td>Catch-up for beginners (optional)</td></tr><tr><td>1</td><td><a href="./">Getting Started</a></td><td>Environment setup, chapter map</td></tr><tr><td>2</td><td><a href="./what-is-mod">What is a Mod</a></td><td>What Mods can do, red lines</td></tr><tr><td>3</td><td><a href="./umm">Understanding UMM</a></td><td>How UMM works, Mod directory, ModEntry</td></tr><tr><td>4</td><td><a href="./first-mod">Minimal Example</a></td><td>Info.json + Main.cs, your first Mod</td></tr><tr><td>5</td><td><a href="./build-debug">Build, Deploy &amp; Debug</a></td><td>Compiling, hot reload, reading logs</td></tr><tr><td>6</td><td><a href="./harmony">Harmony Introduction</a></td><td>Overview of the four patch types</td></tr><tr><td>7</td><td><a href="./harmony-prefix">Prefix Patches</a></td><td>Intercepting methods, modifying parameters</td></tr><tr><td>8</td><td><a href="./harmony-postfix">Postfix Patches</a></td><td>Modifying return values, <code>__state</code></td></tr><tr><td>9</td><td><a href="./harmony-finalizer">Finalizer Patches</a></td><td>Exception handling</td></tr><tr><td>10</td><td><a href="./harmony-magic-params">Magic Parameters</a></td><td><code>__instance</code> / <code>__result</code> / <code>__state</code></td></tr><tr><td>11</td><td><a href="./harmony-attributes">HarmonyPatch In Depth</a></td><td>Target syntax, priorities</td></tr><tr><td>12</td><td><a href="./harmony-lifecycle">Patch Lifecycle</a></td><td>PatchAll / priorities</td></tr><tr><td>13</td><td><a href="./harmony-transpiler">Transpiler Introduction</a></td><td>What IL is</td></tr><tr><td>14</td><td><a href="./harmony-transpiler-practice">Transpiler in Practice</a></td><td>CodeMatcher</td></tr><tr><td>15</td><td><a href="./harmony-manual">Manual Patching</a></td><td>Dynamic patching</td></tr><tr><td>16</td><td><a href="./harmony-reverse">Reverse Patch</a></td><td>Calling game methods in reverse</td></tr><tr><td>17</td><td><a href="./settings">Settings System</a></td><td>Defining and persisting settings</td></tr><tr><td>18</td><td><a href="./settings-ui">Drawing the Settings UI</a></td><td>IMGUI interface</td></tr><tr><td>19</td><td><a href="./finding-methods">Locating Target Methods</a></td><td>dnSpy / ILSpy</td></tr><tr><td>20</td><td><a href="./multiloader">Advanced: Multi-Loader Template</a></td><td>UMM / Melon / BepInEx / Doorstop</td></tr><tr><td>21</td><td><a href="./sarcary">Advanced: Mod API</a></td><td>The Sarcary public API</td></tr><tr><td>22</td><td><a href="./publish">Packaging &amp; Publishing</a></td><td>Releases and publishing</td></tr><tr><td>23</td><td><a href="./github-actions">GitHub Actions CI</a></td><td>CI/CD, private lib repositories</td></tr><tr><td>24</td><td><a href="./guidelines">Mod Development Guidelines</a></td><td>Red lines and quality requirements</td></tr><tr><td>25</td><td><a href="./troubleshooting">FAQ &amp; Troubleshooting</a></td><td>FAQ</td></tr></tbody></table>`,30)])])}const m=e(s,[["render",n]]);export{g as __pageData,m as default};
